import duckdb

con = duckdb.connect()
# Simulación de tabla lakehouse con versionado de commits
con.execute('''
    CREATE TABLE delta_log (version INT, operacion VARCHAR, archivos_agregados INT, timestamp TIMESTAMP);
    CREATE TABLE clientes_lakehouse (id INT, nombre VARCHAR, saldo DECIMAL(10,2), version_commit INT);

    -- Commit 1: Carga inicial
    INSERT INTO delta_log VALUES (1, 'WRITE', 2, CURRENT_TIMESTAMP);
    INSERT INTO clientes_lakehouse VALUES (1, 'Alice', 500.00, 1), (2, 'Bob', 250.00, 1);

    -- Commit 2: Update atomico
    INSERT INTO delta_log VALUES (2, 'UPDATE', 1, CURRENT_TIMESTAMP);
    UPDATE clientes_lakehouse SET saldo = 600.00, version_commit = 2 WHERE id = 1;
''')

res = con.execute('SELECT version, operacion FROM delta_log ORDER BY version').fetchall()
print('Historial de commits:')
for r in res:
    print(f'v{r[0]}: {r[1]}')

activo = con.execute('SELECT nombre, saldo FROM clientes_lakehouse WHERE id = 1').fetchone()
print(f'Estado actual Alice: ${activo[1]}')
